import {blank,demo,validate,uid,now,event,progress,prerequisites,contextBrief,mermaid,vaultFiles,layout,TYPES,STATUSES,RELATIONS,label} from './core.mjs';
import {zip} from './zip.mjs';
import {bindMapPointerSelection} from './map-selection.mjs';
import {mount as mountPele, render as renderPele} from './vendor/pele-1.7.0.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='brancha.workspace.v1';let w,storageOK=true,readRaw=null,etag=null,saving=false,captureState=null;
const localToken=document.querySelector('meta[name="brancha-local-token"]')?.content;
const seed=validate(await (await fetch('./starter-workspace.json')).json());
async function readLive(){const r=await fetch('/api/workspace',{headers:{'X-Brancha-Token':localToken}});if(!r.ok)throw Error('Local companion unavailable');return r.json();}
try{if(localToken){const r=await readLive();w=validate(r.workspace);etag=r.etag;captureState=r.capture;}else{readRaw=localStorage.getItem(KEY);w=readRaw?validate(JSON.parse(readRaw)):structuredClone(seed);if(JSON.stringify(w)!==readRaw){if(readRaw)localStorage.setItem(KEY+'.before-real-projects',readRaw);readRaw=JSON.stringify(w);localStorage.setItem(KEY,readRaw);}}}catch(e){w=blank();storageOK=false;setTimeout(()=>toast('Workspace could not be loaded. '+e.message),200);}
let projectId=w.projects[0]?.id||null,selected=w.nodes.find(n=>n.projectId===projectId&&n.status==='active'&&n.type==='task')?.id||w.nodes[0]?.id,view='map',overview=true,zoom=.82,activityFilter='all';let mapMount=null,modalMount=null;
const icons={goal:'◎',task:'▤',decision:'◇',branch:'⑂',output:'▧',source:'↗'};
const project=()=>w.projects.find(p=>p.id===projectId);
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500);}
function download(name,data,type='application/json'){const blob=data instanceof Blob?data:new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
async function commit(fn){
 if(saving)throw Error("A save is already in progress.");
 const next=structuredClone(w);fn(next);validate(next);
 if(!storageOK)throw Error('Browser storage is unavailable or unreadable. Export your work before continuing in another browser.');
 if(localToken){saving=true;try{const r=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json','X-Brancha-Token':localToken,'If-Match':etag},body:JSON.stringify(next)});const result=await r.json();if(!r.ok)throw Error(result.error);w=validate(result.workspace);etag=result.etag;render();if(result.viewError)toast('Record saved; Obsidian views need attention: '+result.viewError);return;}finally{saving=false;}}
 const current=localStorage.getItem(KEY);if(current!==readRaw)throw Error('This workspace changed in another tab. Reload before editing to preserve both versions.');
 const raw=JSON.stringify(next);try{localStorage.setItem(KEY,raw);}catch(e){throw Error('Could not save to this browser. Export a backup and free browser storage.');}
 w=next;readRaw=raw;render();
}
function modal(title,html){modalMount?.destroy();modalMount=null;$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal').showModal();}
function close(){modalMount?.destroy();modalMount=null;$('#modal').close();}
$('#close-modal').onclick=close;$('#modal').addEventListener('close',()=>{modalMount?.destroy();modalMount=null;});
function options(xs,value){return xs.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(label(x))}</option>`).join('');}
function selectedProject(id){projectId=id;overview=false;selected=w.nodes.find(n=>n.projectId===id&&n.status==='active'&&n.type==='task')?.id||w.nodes.find(n=>n.projectId===id)?.id;view='map';$('#map-search').value='';$('#status-filter').value='all';render();}
function stat(title,value,note,icon){return `<div class="stat"><div class="stat-top">${title}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}<small>${note}</small></div></div>`;}
function renderCapture(){
 const box=$('#capture-strip');box.hidden=!localToken||!captureState;if(box.hidden)return;
 const paused=captureState.paused,stale=!captureState.lastScanAt||Date.now()-Date.parse(captureState.lastScanAt)>20000;
 box.innerHTML=`<div><strong>Codex capture · ${paused?'paused':stale?'starting / check service':'on'}</strong><p>${esc(captureState.error|| (captureState.lastCaptureAt?'Last checkpoint: '+new Date(captureState.lastCaptureAt).toLocaleString()+' · '+captureState.lastTitle:'Waiting for a newly completed Codex turn. Earlier history is not imported.'))}</p><small>Local final responses only · captured reports need evidence review · new unmatched chats go to Codex Inbox${captureState.cloudEnabled?' · Cloud bridge: '+esc(captureState.cloudError||('last checked '+(captureState.lastCloudPullAt?new Date(captureState.lastCloudPullAt).toLocaleTimeString():'connecting'))):''}</small></div><button id="capture-toggle">${paused?'Resume capture':'Pause capture'}</button>`;
 $('#capture-toggle').onclick=async()=>{try{const r=await fetch('/api/capture',{method:'POST',headers:{'Content-Type':'application/json','X-Brancha-Token':localToken},body:JSON.stringify({paused:!paused})});const result=await r.json();if(!r.ok)throw Error(result.error);captureState=result.capture;renderCapture();}catch(e){toast(e.message);}};
}
function render(){renderCapture();
 if(overview||view!=='map'){mapMount?.destroy();mapMount=null;}
 $('.private-label').textContent=localToken?'● Live on this Mac':'● Browser copy';
 const p=project(),ns=w.nodes.filter(n=>overview||n.projectId===projectId);$('#demo-banner').hidden=!w.demo;
 $('#save-status').textContent=storageOK?(localToken?'Live · shared with Obsidian':'Saved in this browser'):'Storage unavailable';
 $('#projects').innerHTML=w.projects.map(p=>`<button class="project-link ${p.id===projectId&&!overview?'active':''}" data-project="${p.id}"><span class="project-bullet"></span>${esc(p.title)}</button>`).join('');
 $$('#projects button').forEach(b=>b.onclick=()=>selectedProject(b.dataset.project));
 $('#title').textContent=overview?'Pick up the thread.':p?.title||'Make room for your next idea.';
 $('#eyebrow').textContent=overview?'YOUR WORK, CONNECTED':'ONE PROJECT. THE WHOLE PICTURE.';
 $('#subtitle').textContent=overview?'Your projects, recent changes and the next steps waiting for you.':p?'Keep the original goal in sight. Let the thinking branch out.':'Start with what you want to achieve. Brancha will keep the trail.';
 $('#breadcrumb').textContent=overview?'Your workspace / Overview':'Your workspace / '+(p?.title||'New beginning');
 $('#resume').disabled=!p;$('#capture').disabled=!p;
 const pr=p?progress(w,p):{done:0,total:0};
 $('#stats').innerHTML=stat(overview?'Projects':'Original goals',overview?w.projects.length:pr.done+(pr.total?' / '+pr.total:''),overview?'in your workspace':'with evidence','◎')+stat('In motion',ns.filter(n=>n.status==='active').length,'active items','↗')+stat('Needs attention',ns.filter(n=>n.status==='blocked').length,'blocked items','◷')+stat('New directions',ns.filter(n=>n.type==='branch').length,'branches to explore','⑂');
 $('#overview').hidden=!overview;$('#workspace').hidden=overview||!p;
 if(overview){renderOverview();return;}
 if(!p){$('#overview').hidden=false;$('#overview').innerHTML='<div class="empty"><h2>Start with a single request.</h2><p>A home project, something to learn, a plan for work.<br>You don’t need a perfect plan to begin.</p><button class="primary" id="empty-new">Create your first project →</button></div>';$('#empty-new').onclick=newProject;return;}
 $$('[role=tab]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-selected',String(b.dataset.view===view));});
 for(const name of ['map','activity','brief'])$('#'+name+'-view').hidden=view!==name;
 if(view==='map')renderMap();if(view==='activity')renderActivity();if(view==='brief')renderBrief();renderInspector();
}
function selectMapItem(id){
 if(!w.nodes.some(n=>n.id===id&&n.projectId===projectId))return;
 selected=id;$('#map-stage').querySelectorAll('.pele-node').forEach(x=>x.classList.toggle('is-selected',x.getAttribute('data-id')===id));renderInspector();
}
function renderMap(){
 mapMount?.destroy();mapMount=null;
 const q=$('#map-search').value.toLowerCase(),status=$('#status-filter').value;
 const matches=w.nodes.filter(n=>n.projectId===projectId&&(status==='all'||n.status===status)&&(!q||(n.title+' '+n.detail).toLowerCase().includes(q)));
 const nodes=matches.slice(0,120),ids=new Set(nodes.map(n=>n.id)),filtered={...w,nodes,edges:w.edges.filter(e=>ids.has(e.from)&&ids.has(e.to))};
 const stage=$('#map-stage');stage.style.width='100%';stage.style.height='100%';stage.innerHTML='';
 if(!nodes.length){stage.innerHTML='<div class="empty">'+(w.nodes.some(n=>n.projectId===projectId)?'No items match this filter.':'Your map starts here. Add a task, decision, source or branch.')+'</div>';return;}
 const source=mermaid(filtered,projectId).replace('flowchart LR',nodes.length>7?'flowchart TB':'flowchart LR');
 mapMount=mountPele(stage,source,{fontSize:15,padding:28,images:false,links:false,idPrefix:'branchaMap',maxEdges:1000,zoom:{always:true,controls:false,maxScale:3},onRender:()=>{
   stage.querySelectorAll('.pele-node[data-id]').forEach(el=>{const n=nodes.find(n=>n.id===el.getAttribute('data-id'));if(!n)return;
     el.dataset.status=n.status;el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label',n.title+', '+n.type+', '+n.status);el.classList.toggle('is-selected',n.id===selected);
     const choose=()=>selectMapItem(n.id);
     el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};
   });
 },onError:()=>toast('This map could not be drawn. Narrow it with search or status; your records are preserved.')});
 mapMount.zoom?.zoomTo(Math.max(mapMount.zoom.fit,.8));
 $('#zoom-reset').textContent='Fit';
 $('#map-engine-note').textContent=matches.length>120?'Pele · 120 of '+matches.length+' items · filter to focus':'Pele · select an item · drag or zoom to explore';
}
function renderInspector(){
 const n=w.nodes.find(n=>n.id===selected&&n.projectId===projectId);if(!n){$('#inspector').innerHTML='<p class="eyebrow">THE DETAILS</p><h2>A little context goes a long way.</h2><p>Select a card to see its evidence, decisions and next step.</p>';return;}
 const deps=prerequisites(w,n.id),blocked=deps.filter(x=>x.status!=='done');const connections=w.edges.filter(e=>e.from===n.id||e.to===n.id);
 $('#inspector').innerHTML=`<p class="eyebrow">${icons[n.type]} &nbsp; ${n.type.toUpperCase()} / CONTEXT</p><span class="status ${n.status}">${label(n.status)}</span><h2>${esc(n.title)}</h2><div><p>${esc(n.detail||'Add a note to keep the context.')}</p>${blocked.length?`<h3>Waiting on</h3><p class="red">${esc(blocked.map(d=>d.title).join(', '))}</p>`:''}${n.type==='decision'?`<h3>Why this direction</h3><p>${esc(n.rationale||'Not recorded yet.')}</p><h3>Other options</h3><p>${esc(n.alternatives||'Not recorded yet.')}</p><h3>Consequences</h3><p>${esc(n.consequence||'Not recorded yet.')}</p>`:''}${n.evidence?`<h3>Evidence</h3><p class="evidence">${esc(n.evidence)}</p>`:''}</div><div><div class="next-box"><h3>Next small step</h3><p>${esc(n.next||'Record the next action when you finish this session.')}</p></div>${connections.length?'<h3>Connected to</h3>'+connections.map(e=>{const o=w.nodes.find(x=>x.id===(e.from===n.id?e.to:e.from));return `<div class="connection"><button data-jump="${o.id}">${esc(o.title)} ↗</button><small>${esc(e.from===n.id?'Leads to · '+label(e.type):label(e.type))}${o.projectId!==projectId?' · another project':''}</small></div>`;}).join(''):''}<div class="edit-row"><button id="edit-node">Edit item</button><button id="branch-node">⑂ Branch</button><button id="link-node">Connect</button></div></div>`;
 $('#edit-node').onclick=()=>nodeForm(n);$('#branch-node').onclick=()=>nodeForm(null,n);$('#link-node').onclick=()=>linkForm(n);
 $$('[data-jump]').forEach(b=>b.onclick=()=>{const node=w.nodes.find(n=>n.id===b.dataset.jump);projectId=node.projectId;selected=node.id;render();});
}
const dayKey=d=>{const x=new Date(d);return [x.getFullYear(),x.getMonth()+1,x.getDate()].join('-');};
function activityHTML(events){return events.length?events.slice().sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).map(e=>`<article class="activity-item"><small>${new Date(e.at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${esc(w.projects.find(p=>p.id===e.projectId)?.title)}</small><p>${esc(e.text)}</p>${e.nodeId?`<button data-activity="${e.nodeId}">Open item ↗</button>`:''}</article>`).join(''):'<div class="empty">No recorded activity for this period.</div>';}
function bindActivity(){ $$('[data-activity]').forEach(b=>b.onclick=()=>{const n=w.nodes.find(n=>n.id===b.dataset.activity);projectId=n.projectId;selected=n.id;overview=false;view='map';render();});}
function renderActivity(){
 const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);
 const events=w.events.filter(e=>e.projectId===projectId&&(activityFilter==='all'||dayKey(e.at)===dayKey(activityFilter==='today'?new Date():yesterday)));
 $('#activity-view').innerHTML=`<div class="activity-controls"><span>What changed, and when</span><select id="activity-filter">${options(['all','today','yesterday'],activityFilter)}</select></div><div class="activity-list">${activityHTML(events)}</div>`;$('#activity-filter').onchange=e=>{activityFilter=e.target.value;renderActivity();};bindActivity();
}
function renderBrief(){const p=project(),pr=progress(w,p),unmapped=w.nodes.filter(n=>n.projectId===p.id&&!n.criteria.length&&!['goal','source','branch'].includes(n.type));$('#brief-view').innerHTML=`<div class="brief-body"><p class="eyebrow">THE STARTING POINT</p><h2>What you originally asked for</h2><div class="prompt-box">${esc(p.prompt)}</div><p class="brief-note">The original request is preserved. Record a change of direction as a decision or branch so the history remains clear.</p><h2>What success looks like</h2>${pr.criteria.length?pr.criteria.map(c=>`<div class="criterion"><span class="check">${c.evidence.length?'✓':'○'}</span>${esc(c.text)}<p>${c.evidence.length?'Evidence recorded in: '+esc(c.evidence.map(n=>n.title).join(', ')):'No completed item with evidence linked yet.'}</p></div>`).join(''):'<p class="brief-note">No criteria recorded.</p>'}<p class="brief-note">Progress counts criteria linked to completed work with evidence. It is a user-recorded measure, not independent verification or an estimate of effort.</p>${unmapped.length?`<h2>Check the connection to your goal</h2><p class="brief-note">${unmapped.length} work item(s) have no success criterion attached: ${esc(unmapped.map(n=>n.title).join(', '))}. Link them, or deliberately keep them as supporting work.</p>`:''}<button id="add-criterion">＋ Add a success criterion</button></div>`;$('#add-criterion').onclick=criterionForm;}
function renderOverview(){const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const es=w.events.filter(e=>dayKey(e.at)===dayKey(yesterday));$('#overview').innerHTML=`<div class="companion-note"><strong>${localToken?'Live on this Mac · Obsidian + skill':(w.demo?'Example workspace · browser copy':'Your projects · browser copy')}</strong><p>${localToken?'Updates to the shared record appear here automatically. Pick a project, capture a checkpoint, or resume with AI.':(w.demo?'Fictional examples to explore. Create a project to begin your own record.':'Switch projects below. Live Obsidian updates run in the local companion.')}</p><button id="workflow-help">How live updates work ↗</button></div><div class="overview-heading"><h2>Your projects</h2><button id="portfolio-map">View the connected map ↗</button></div><div class="overview-grid">${w.projects.map(p=>{const pr=progress(w,p),next=w.nodes.find(n=>n.projectId===p.id&&n.status==='active'&&n.next);return `<button class="overview-card" data-open="${p.id}"><p class="eyebrow">PROJECT</p><h2>${esc(p.title)}</h2><p>${esc(next?.next||'Choose the next small step.')}</p><div class="progress-track"><span style="width:${pr.total?100*pr.done/pr.total:0}%"></span></div><small>${pr.done} of ${pr.total} goals have evidence <span style="float:right">Open map ↗</span></small></button>`;}).join('')}</div><div class="overview-activity"><h2>Yesterday, across your projects</h2><div class="activity-list">${activityHTML(es)}</div></div>`;$('#workflow-help').onclick=guide;$$('[data-open]').forEach(b=>b.onclick=()=>selectedProject(b.dataset.open));$('#portfolio-map').onclick=portfolioMap;bindActivity();}
function newProject(){modal('Start a new thread',`<p class="form-note">Use your own words. A good starting point is what you want to achieve, what matters and how you’ll know it’s finished.${w.demo?' Creating your first project starts a clean workspace; the fictional example is not copied.':''}</p><form id="project-form" class="form-grid"><label class="full">Project name<input name="title" required maxlength="200" placeholder="A project, a plan, a new idea…"></label><label class="full">Your original request<textarea name="prompt" required placeholder="Help me…"></textarea></label><label class="full">What would success look like? One outcome per line<textarea name="criteria" required placeholder="A clear plan I can follow&#10;A result I can test"></textarea></label><p class="error full" id="form-error"></p><div class="actions full"><button class="primary">Create project →</button></div></form>`);$('#project-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),id=uid(),title=f.get('title').trim(),prompt=f.get('prompt').trim(),criteria=f.get('criteria').split('\n').map(t=>t.trim()).filter(Boolean).map(text=>({id:uid(),text}));if(!title||!prompt||!criteria.length)throw Error('Add a name, request and at least one outcome.');await commit(n=>{if(n.demo)Object.assign(n,blank());n.projects.push({id,title,prompt,criteria,createdAt:now()});const goal={id:uid(),projectId:id,title:'The original goal',type:'goal',status:'active',detail:prompt,criteria:[],evidence:'',next:'Choose the first concrete step.',rationale:'',alternatives:'',consequence:''};n.nodes.push(goal);event(n,id,'Started the project and preserved the original request.',goal.id);});close();selectedProject(id);toast('Your project is ready. Add the first step or decision.');}catch(err){$('#form-error').textContent=err.message;}};}
function nodeForm(existing=null,parent=null){
 const p=project(),n=existing||{title:'',type:parent?'branch':'task',status:parent?'parked':'planned',detail:'',evidence:'',next:'',criteria:[],rationale:'',alternatives:'',consequence:''};
 modal(existing?'Keep the context current':parent?'Let the idea branch out':'Add to the map',`<p class="form-note">Capture enough to pick this up later. Completed work needs evidence. Only link an outcome when this item can satisfy it in full; leave small supporting subtasks unlinked.</p><form id="node-form" class="form-grid"><label class="full">Title<input name="title" value="${esc(n.title)}" maxlength="200" required></label><label>Kind<select name="type" id="kind">${options(TYPES,n.type)}</select></label><label>Status<select name="status">${options(STATUSES,n.status)}</select></label><label class="full">Context / what happened<textarea name="detail">${esc(n.detail)}</textarea></label><label class="full">Next small step<input name="next" value="${esc(n.next)}"></label><label class="full">Evidence or source (required for done)<textarea name="evidence" placeholder="What was tested, observed or approved? Include a file or link if you have one.">${esc(n.evidence)}</textarea></label><div class="full form-grid" id="decision-fields" ${n.type!=='decision'?'hidden':''}><label class="full">Why this direction?<textarea name="rationale">${esc(n.rationale)}</textarea></label><label class="full">Other options considered<textarea name="alternatives">${esc(n.alternatives)}</textarea></label><label class="full">Consequences / tradeoffs<textarea name="consequence">${esc(n.consequence)}</textarea></label></div><div class="full field">Which outcomes will this item fully satisfy when done?<div class="checklist">${p.criteria.map(c=>`<label><input type="checkbox" name="criteria" value="${c.id}" ${n.criteria.includes(c.id)?'checked':''}>${esc(c.text)}</label>`).join('')}</div></div>${!existing&&!parent?`<label class="full">Connect from an existing item (optional)<select name="from"><option value="">No connection yet</option>${w.nodes.filter(x=>x.projectId===p.id).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><label class="full">The new item…<select name="relation">${options(RELATIONS,'implements')}</select></label>`:''}<p class="error full" id="form-error"></p><div class="actions full"><button class="primary">Save to the map</button></div></form>`);
 $('#kind').onchange=e=>$('#decision-fields').hidden=e.target.value!=='decision';
 $('#node-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),item={id:existing?.id||uid(),projectId:p.id,criteria:f.getAll('criteria')};for(const k of ['title','type','status','detail','evidence','next','rationale','alternatives','consequence'])item[k]=f.get(k)?.trim()||'';await commit(next=>{if(existing){next.nodes[next.nodes.findIndex(x=>x.id===existing.id)]=item;}else{next.nodes.push(item);const from=parent?.id||f.get('from');if(from)next.edges.push({id:uid(),from,to:item.id,type:parent?'branches_from':f.get('relation')});}event(next,p.id,`${existing?'Updated':'Added'} ${item.type}: ${item.title} (${existing?existing.status+' → ':''}${item.status}).${item.next?' Next: '+item.next:''}`,item.id);Object.assign(next.events.at(-1),{before:existing?structuredClone(existing):null,after:structuredClone(item)});});selected=item.id;close();render();toast('Context saved.');}catch(err){$('#form-error').textContent=err.message;}};
}
function linkForm(n){modal('Connect the work',`<p class="form-note">Choose what this item depends on, branches from, implements or is informed by. Dependencies can cross projects.</p><form id="link-form" class="form-grid"><label class="full">${esc(n.title)}…<select name="type">${options(RELATIONS,'depends_on')}</select></label><label class="full">This item<select name="from" required>${w.nodes.filter(x=>x.id!==n.id).map(x=>`<option value="${x.id}">${esc(w.projects.find(p=>p.id===x.projectId).title)} / ${esc(x.title)}</option>`).join('')}</select></label><p class="error full" id="form-error"></p><div class="actions full"><button class="primary">Save connection</button></div></form>`);$('#link-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await commit(next=>{next.edges.push({id:uid(),from:f.get('from'),to:n.id,type:f.get('type')});event(next,n.projectId,`Connected ${n.title}: ${label(f.get('type'))} ${next.nodes.find(x=>x.id===f.get('from'))?.title}.`,n.id);});close();toast('Connection saved.');}catch(err){$('#form-error').textContent=err.message;}};}
function criterionForm(){modal('Add a success criterion',`<p class="form-note">This appends an outcome to the current plan and records the scope change in activity. The original request is preserved.</p><form id="criterion-form"><label class="field">Outcome<textarea name="text" required maxlength="2000"></textarea></label><p id="form-error" class="error"></p><div class="actions"><button class="primary">Add outcome</button></div></form>`);$('#criterion-form').onsubmit=async e=>{e.preventDefault();try{const text=new FormData(e.target).get('text').trim();if(!text)throw Error('Enter an outcome.');await commit(n=>{n.projects.find(p=>p.id===projectId).criteria.push({id:uid(),text});event(n,projectId,'Added success criterion: '+text);});close();}catch(err){$('#form-error').textContent=err.message;}};}
function showResume(){const text=contextBrief(w,projectId,selected);modal('Ready to pick this up',`<p class="form-note">Copy this bounded brief into your preferred AI chat. It carries the original request, evidence, decisions, dependencies and next action. Nothing is sent automatically.</p><label class="sr-only" for="resume-text">Resume brief</label><textarea id="resume-text" class="brief-text">${esc(text)}</textarea><div class="actions"><button id="download-brief">Download .md</button><button id="copy-brief" class="primary">Copy brief</button></div>`);$('#copy-brief').onclick=async()=>{try{await navigator.clipboard.writeText($('#resume-text').value);toast('Brief copied. Paste it into your AI chat.');}catch{ $('#resume-text').select();toast('Use your browser’s copy command to copy the selected brief.');}};$('#download-brief').onclick=()=>download('brancha-resume.md',$('#resume-text').value,'text/markdown');}
function portfolioMap(){
 const ps=w.projects.slice(0,100),ids=new Set(ps.map(p=>p.id)),safe=x=>x.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;');
 const counts=new Map();for(const e of w.edges){const a=w.nodes.find(n=>n.id===e.from),b=w.nodes.find(n=>n.id===e.to);if(a.projectId!==b.projectId&&ids.has(a.projectId)&&ids.has(b.projectId)){const key=a.projectId+':'+b.projectId;counts.set(key,(counts.get(key)||0)+1);}}
 const source=['flowchart LR',...ps.map(p=>`${p.id}["${safe(p.title)}"]`),...Array.from(counts,([key,count])=>{const [a,b]=key.split(':');return `${a} -->|"${count} connections"| ${b}`;})].join('\n');
 modal('The connected workspace',`<p class="form-note">Each card is a project. Lines show recorded connections between work in different projects. Select a project to open its detailed map.</p><div id="portfolio-pele" class="portfolio-viewport"></div>${counts.size?'':'<p class="form-note">No cross-project connections recorded yet. Use Connect on any map item to add one.</p>'}`);
 if(!ps.length){$('#portfolio-pele').textContent='Create your first project to start the map.';return;}
 modalMount=mountPele($('#portfolio-pele'),source,{images:false,links:false,zoom:{always:true},idPrefix:'branchaPortfolio',onRender:()=>{$$('#portfolio-pele .pele-node[data-id]').forEach(el=>{const id=el.getAttribute('data-id'),p=ps.find(p=>p.id===id);if(!p)return;el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label','Open '+p.title);const choose=()=>{close();selectedProject(id);};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});}});
}
function showMermaid(){const code=mermaid(w,projectId);modal('Pele diagram · Mermaid source',`<p class="form-note">Rendered locally with Pele 1.7.0. The diagram keeps portable Mermaid syntax for use in Obsidian and other tools.</p><div id="mermaid-render" class="mermaid-render"></div><details style="margin-top:15px"><summary>Diagram source</summary><textarea class="brief-text" id="mermaid-code">${esc(code)}</textarea></details><div class="actions"><button id="download-svg">Download SVG</button><button id="download-mermaid">Download .mmd</button></div>`);$('#download-mermaid').onclick=()=>download('brancha-map.mmd',code,'text/plain');modalMount=mountPele($('#mermaid-render'),code,{images:false,links:false,zoom:{always:true},idPrefix:'branchaExport'});$('#download-svg').onclick=()=>{try{const r=renderPele(code,{images:false,links:false,responsive:false,fontFamily:'sans-serif'});download('brancha-map.svg',r.svg,'image/svg+xml');}catch(e){toast(e.message);}};}
function chatGPTGuide(){
 const title=overview?'the project I choose':project()?.title||'the project I choose';
 const prompt=`Use Brancha Connect to resume ${title}. Keep meaningful decisions, branches, evidence and next steps updated without asking me each time. When I name another project, save any meaningful unsaved work here and resume that project. Keep this active for the rest of this chat. Preserve the original goal and keep reported results separate from verified completion.`;
 const bridge=captureState?.cloudEnabled?(captureState.cloudError?'The local cloud bridge needs attention: '+captureState.cloudError:'The local cloud bridge is enabled. New ChatGPT checkpoints are checked about every 30 seconds while this Mac is online.'):'The optional cloud bridge has not been configured for this local workspace.';
 modal('Brancha in ChatGPT and Codex',`<div class="guide-grid"><div><h3>ChatGPT Connect</h3><p>Resume projects and save meaningful checkpoints during a chat using the Brancha plugin and skill. Your private cloud workspace stays available when your Mac is off.</p><ol><li>Open <a href="https://chatgpt.com/plugins" target="_blank" rel="noopener noreferrer">ChatGPT Plugins</a> and find your personal Brancha Connect plugin.</li><li>Connect or sign in if prompted. Start a new Work chat and type @ to select Brancha.</li><li>Use the starter below. After activation, the skill guides checkpoints at meaningful milestones in that chat.</li></ol></div><div><h3>Codex Local</h3><p>${captureState?'Your local capture service is configured. Completed Codex turns become unverified source checkpoints automatically. Check the capture bar for its current status.':'Run the local companion to capture completed Codex turns automatically.'} The browser workspace and Obsidian read the same local record.</p><p>${esc(bridge)}</p><p>Local Codex responses stay local. The bridge appends new cloud checkpoints; it does not overwrite your existing local records or upload local changes.</p></div></div><label class="field">Starter for your ChatGPT chat<textarea id="chatgpt-starter" rows="4">${esc(prompt)}</textarea></label><p class="form-note">ChatGPT must have Brancha selected or activated for the task. This does not passively watch every ChatGPT conversation. After connecting, save one checkpoint and check that it appears in your local map and Obsidian.</p>${captureState?.cloudEnabled?'':'<p><a href="https://github.com/fuzzwin/brancha/blob/main/cloud/README.md" target="_blank" rel="noopener noreferrer">First-time ChatGPT service setup →</a></p>'}<div class="actions"><button id="copy-chatgpt-starter" class="primary">Copy starter</button></div>`);
 $('#copy-chatgpt-starter').onclick=async()=>{try{await navigator.clipboard.writeText($('#chatgpt-starter').value);toast('Starter copied. Paste it into a ChatGPT chat with Brancha selected.');}catch{$('#chatgpt-starter').select();toast('Use your browser’s copy command to copy the selected starter.');}};
}
function guide(){modal('How your companion works',`<p class="form-note">Brancha turns scattered AI sessions into a project you can return to.</p><div class="guide-grid"><div><h3>01 / Start with the request</h3><p>Keep the original prompt and a few concrete outcomes. They are your reference point when the work changes direction.</p></div><div><h3>02 / Let the map grow</h3><p>Add tasks, decisions, outputs and sources. Branch off interesting ideas and park them without losing the main goal.</p></div><div><h3>03 / Close the loop</h3><p>Codex Local captures completed turns automatically. In a ChatGPT task with Brancha activated, the plugin and skill guide meaningful checkpoints. Activity keeps the dated trail.</p></div><div><h3>04 / Resume anywhere</h3><p>Resume through the ChatGPT plugin or copy a bounded brief into another AI tool. Keep your dependency maps and linked notes in Obsidian.</p></div></div><p class="form-note">${localToken?'LIVE ON THIS MAC: the app and Brancha skill share the vault’s brancha.json. Changes refresh the app and regenerate Obsidian views. Keep personal notes in Notes; Generated is replaced.':'BROWSER COPY: edits stay in this browser. Use Backup / Import to move a copy. Codex Local and the private ChatGPT service have their own records.'} ${captureState?.cloudEnabled?'The cloud-to-local bridge is configured. New cloud checkpoints are appended locally while the Mac is online.':'A cloud-to-local bridge can connect the optional ChatGPT service after setup.'} Pause from the capture bar to skip local activity and defer cloud pulls. Captured reports need evidence review before goals are marked complete.</p><div class="actions"><button id="guide-chatgpt" class="primary">Use with ChatGPT</button><button id="guide-backup">Download backup</button><button id="guide-import">Import backup</button></div>`);$('#guide-chatgpt').onclick=()=>{close();chatGPTGuide();};$('#guide-backup').onclick=()=>download('brancha-workspace.json',JSON.stringify(w,null,2));$('#guide-import').onclick=()=>{close();$('#import-file').click();};}
$('#add-project').onclick=newProject;$('#add-project-mini').onclick=newProject;$('#start-fresh').onclick=newProject;$('#capture').onclick=()=>nodeForm();$('#resume').onclick=showResume;$('#mermaid').onclick=showMermaid;$('#chatgpt-guide').onclick=chatGPTGuide;$('#guide').onclick=guide;$('#workspace-options').onclick=guide;
$('#home').onclick=()=>{overview=true;render();};$('#brand').onclick=e=>{e.preventDefault();overview=true;render();};
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#map-search').oninput=renderMap;$('#status-filter').onchange=renderMap;
$('#zoom-in').onclick=()=>mapMount?.zoom?.zoomBy(1.25);$('#zoom-out').onclick=()=>mapMount?.zoom?.zoomBy(.8);$('#zoom-reset').onclick=()=>mapMount?.zoom?.reset();
$('#export-json').onclick=()=>download('brancha-workspace.json',JSON.stringify(w,null,2));$('#export-vault').onclick=()=>{try{download('Brancha-Obsidian.zip',zip(vaultFiles(w)));toast('Vault snapshot exported. Unzip it and open the folder as an Obsidian vault.');}catch(e){toast(e.message);}};
$('#import-json').onclick=()=>{if(localToken){toast('Live workspace imports are disabled to protect shared history. Use the skill for incremental changes, or import into the hosted browser copy.');return;}$('#import-file').click();};
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>8*1024*1024)throw Error('Choose a workspace smaller than 8 MB.');const imported=validate(JSON.parse(await file.text()));modal('Import this workspace?',`<p class="form-note">${imported.projects.length} projects and ${imported.nodes.length} map items. This replaces the browser workspace. Download your current backup first if you want to keep it.</p><div class="actions"><button id="backup-before-import">Back up current</button><button id="confirm-import" class="primary">Replace workspace</button></div><p class="error" id="import-error"></p>`);$('#backup-before-import').onclick=()=>download('brancha-before-import.json',JSON.stringify(w,null,2));$('#confirm-import').onclick=async()=>{try{await commit(n=>Object.assign(n,imported));close();projectId=w.projects[0]?.id;selected=w.nodes[0]?.id;overview=false;render();toast('Workspace imported.');}catch(err){$('#import-error').textContent=err.message;}};}catch(err){toast('Import stopped: '+err.message);}};
window.addEventListener('storage',e=>{if(!localToken&&e.key===KEY)toast('Workspace changed in another tab. Reload before editing.');});
bindMapPointerSelection($('#map-stage'),selectMapItem);
render();

if(localToken)setInterval(async()=>{if(saving||$('#modal').open)return;try{const r=await readLive();captureState=r.capture;renderCapture();if(r.etag!==etag){w=validate(r.workspace);etag=r.etag;if(!w.projects.some(p=>p.id===projectId)){projectId=w.projects[0]?.id;selected=w.nodes.find(n=>n.projectId===projectId)?.id;}render();toast('Shared record updated.');}$('#save-status').textContent=r.viewError?'Record saved · vault view issue':'Live · shared with Obsidian';}catch{$('#save-status').textContent='Disconnected · restart local companion';}},2000);
